-- Name: audit_domain_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_domain_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE oldrow jsonb; newrow jsonb; oldstate jsonb; newstate jsonb;
  entity uuid; order_id uuid; actor uuid; field text;
BEGIN
  IF TG_OP <> 'INSERT' THEN oldrow:=to_jsonb(OLD); END IF;
  IF TG_OP <> 'DELETE' THEN newrow:=to_jsonb(NEW); END IF;
  IF TG_TABLE_NAME='seat_holds' THEN
    entity:=COALESCE(newrow,oldrow)->>'holdSessionId';
  ELSE entity:=COALESCE(newrow,oldrow)->>'id'; END IF;
  FOREACH field IN ARRAY ARRAY['status','expiresAt','checkedInAt','cancelledAt','seatId','expectedSeatIds'] LOOP
    IF oldrow ? field THEN oldstate:=COALESCE(oldstate,'{}'::jsonb)||jsonb_build_object(field,oldrow->field); END IF;
    IF newrow ? field THEN newstate:=COALESCE(newstate,'{}'::jsonb)||jsonb_build_object(field,newrow->field); END IF;
  END LOOP;
  IF TG_OP='UPDATE' AND oldstate IS NOT DISTINCT FROM newstate THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME='orders' THEN order_id:=entity;
  ELSIF TG_TABLE_NAME IN ('tickets','refunds') THEN order_id:=COALESCE(newrow,oldrow)->>'orderId';
  ELSE SELECT o.id INTO order_id FROM orders o WHERE o."holdSessionId"=entity ORDER BY o."createdAt" DESC LIMIT 1;
  END IF;
  actor:=NULLIF(current_setting('app.actor_id',true),'')::uuid;
  VALUES(TG_TABLE_NAME,entity,order_id,actor,CASE WHEN actor IS NULL THEN 'SYSTEM' ELSE 'USER' END,TG_OP,oldstate,newstate);
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: claim_hold_v1(uuid, uuid, text, uuid[], uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_hold_v1(p_show uuid, p_user uuid, p_session text, p_seats uuid[], p_id uuid, p_token uuid) RETURNS TABLE(status text, valid integer, "claimedSeatIds" uuid[], "serverTime" timestamp with time zone, id uuid, "expiresAt" timestamp with time zone, "seatIds" uuid[])
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  claim_result record;
BEGIN
  IF cardinality(p_seats) IS NULL OR cardinality(p_seats) NOT BETWEEN 1 AND 2000
     OR EXISTS (SELECT 1 FROM unnest(p_seats) AS x WHERE x IS NULL)
     OR cardinality(p_seats) <> (SELECT count(DISTINCT x) FROM unnest(p_seats) AS x)
  THEN
    RAISE EXCEPTION 'Invalid seat list' USING ERRCODE = '22023';
  END IF;

  WITH requested AS (SELECT p_seats AS ids),
  available_show AS MATERIALIZED (
    SELECT sh.id, sh.status,
      (SELECT count(*)::int FROM public.seats s
       JOIN public.seat_categories c ON c.id=s."categoryId"
       WHERE s."showtimeId"=sh.id AND s.id=ANY(p_seats)
         AND c.price IS NOT NULL) AS valid
    FROM public.showtimes sh WHERE sh.id=p_show FOR SHARE
  ), authority AS (
    SELECT p_id,available_show.id,p_user,p_session,p_token,
      clock_timestamp()+interval '10 minutes',requested.ids
    FROM available_show CROSS JOIN requested
    WHERE available_show.status='ON_SALE' AND available_show.valid=cardinality(p_seats)
    ON CONFLICT ("showtimeId","userId","sessionHash") DO UPDATE SET
      "expectedSeatIds"=CASE
        WHEN existing."expiresAt"<=EXCLUDED."expiresAt"-interval '10 minutes'
          THEN EXCLUDED."expectedSeatIds"
        ELSE ARRAY(SELECT DISTINCT seat_id FROM unnest(existing."expectedSeatIds" ||
          EXCLUDED."expectedSeatIds") AS seat_id ORDER BY seat_id) END,
      token=CASE WHEN existing."expiresAt"<=EXCLUDED."expiresAt"-interval '10 minutes'
        THEN EXCLUDED.token ELSE existing.token END,
      "expiresAt"=CASE WHEN existing."expiresAt"<=EXCLUDED."expiresAt"-interval '10 minutes'
        THEN EXCLUDED."expiresAt" ELSE existing."expiresAt" END
    RETURNING existing.id,existing.token,existing."expiresAt",existing."showtimeId"
  ), claimed AS (
    SELECT seat_id,authority."showtimeId",authority.id,authority.token,authority."expiresAt"
    FROM authority CROSS JOIN requested CROSS JOIN unnest(requested.ids) AS seat_id
    ORDER BY seat_id
    ON CONFLICT ("seatId") DO UPDATE SET
      "holdSessionId"=EXCLUDED."holdSessionId",token=EXCLUDED.token,
      "expiresAt"=EXCLUDED."expiresAt",
      "acquiredAt"=CASE WHEN existing.token=EXCLUDED.token
        THEN existing."acquiredAt" ELSE clock_timestamp() END
    WHERE existing."expiresAt"<=clock_timestamp()
      OR (existing."holdSessionId"=EXCLUDED."holdSessionId" AND existing.token=EXCLUDED.token)
    RETURNING existing."seatId"
  )
  SELECT available_show.status::text,available_show.valid,
    COALESCE((SELECT array_agg(claimed."seatId" ORDER BY claimed."seatId") FROM claimed),'{}'::uuid[])
      AS claimed_ids
  INTO claim_result FROM available_show;

  IF NOT FOUND THEN RETURN; END IF;
  -- Separate SQL command deliberately: do not fold into the claim CTE snapshot.
  RETURN QUERY
    SELECT claim_result.status,claim_result.valid,claim_result.claimed_ids,
      clock_timestamp(),hs.id,hs."expiresAt",
      COALESCE(array_agg(h."seatId" ORDER BY h."seatId")
        FILTER (WHERE h."seatId" IS NOT NULL),'{}'::uuid[])
    FROM (SELECT 1) anchor
    LEFT JOIN public.hold_sessions hs ON hs."showtimeId"=p_show
      AND hs."userId"=p_user AND hs."sessionHash"=p_session
      AND hs."expiresAt">clock_timestamp()
    LEFT JOIN public.seat_holds h ON h."holdSessionId"=hs.id
      AND h.token=hs.token AND h."expiresAt">clock_timestamp()
    GROUP BY hs.id,hs."expiresAt";
END;
$$;


--
-- Name: claim_hold_v2(uuid, uuid, text, uuid[], uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_hold_v2(p_show uuid, p_user uuid, p_session text, p_seats uuid[], p_id uuid, p_token uuid) RETURNS TABLE(status text, valid integer, "claimedSeatIds" uuid[], "serverTime" timestamp with time zone, id uuid, "expiresAt" timestamp with time zone, "seatIds" uuid[])
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  result record;
  rejected uuid[];
BEGIN
  SELECT * INTO result FROM public.claim_hold_v1(p_show,p_user,p_session,p_seats,p_id,p_token);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Hold show missing' USING ERRCODE='H0001';
  END IF;
  IF result.status <> 'ON_SALE' THEN
    RAISE EXCEPTION 'Hold show closed' USING ERRCODE='H0002';
  END IF;
  IF result.valid <> cardinality(p_seats) THEN
    RAISE EXCEPTION 'Hold seats invalid or unpriced' USING ERRCODE='H0003';
  END IF;
  IF cardinality(result."claimedSeatIds") <> cardinality(p_seats) THEN
    SELECT array_agg(x ORDER BY x) INTO rejected
      FROM unnest(p_seats) AS x WHERE NOT (x=ANY(result."claimedSeatIds"));
    RAISE EXCEPTION 'Hold seat conflict' USING ERRCODE='H0004',
      DETAIL=array_to_json(rejected)::text;
  END IF;
  IF result.id IS NULL OR result."expiresAt" IS NULL OR cardinality(result."seatIds")=0 THEN
    RAISE EXCEPTION 'Hold expired after lock wait' USING ERRCODE='H0005';
  END IF;
  RETURN QUERY SELECT result.status,result.valid,result."claimedSeatIds",result."serverTime",
    result.id,result."expiresAt",result."seatIds";
END;
$$;


--
-- Name: claim_hold_v3(uuid, uuid, text, uuid[], uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_hold_v3(p_show uuid, p_user uuid, p_session text, p_seats uuid[], p_id uuid, p_token uuid) RETURNS TABLE(failure text, "rejectedSeatIds" uuid[], "serverTime" timestamp with time zone, id uuid, "expiresAt" timestamp with time zone, "seatIds" uuid[])
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  result record;
  error_code text;
  error_constraint text;
BEGIN
  BEGIN
    SELECT * INTO result FROM public.claim_hold_v1(p_show,p_user,p_session,p_seats,p_id,p_token);
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='H0001'; END IF;
    IF result.status <> 'ON_SALE' THEN RAISE EXCEPTION USING ERRCODE='H0002'; END IF;
    IF result.valid <> cardinality(p_seats) THEN RAISE EXCEPTION USING ERRCODE='H0003'; END IF;
    IF cardinality(result."claimedSeatIds") <> cardinality(p_seats) THEN
      SELECT array_agg(x ORDER BY x) INTO "rejectedSeatIds"
        FROM unnest(p_seats) AS x WHERE NOT (x=ANY(result."claimedSeatIds"));
      RAISE EXCEPTION USING ERRCODE='H0004';
    END IF;
    IF result.id IS NULL OR result."expiresAt" IS NULL OR cardinality(result."seatIds")=0 THEN
      RAISE EXCEPTION USING ERRCODE='H0005';
    END IF;
    "serverTime" := result."serverTime";
    id := result.id;
    "expiresAt" := result."expiresAt";
    "seatIds" := result."seatIds";
    "rejectedSeatIds" := '{}'::uuid[];
  EXCEPTION
    WHEN SQLSTATE 'H0001' OR SQLSTATE 'H0002' OR SQLSTATE 'H0003'
      OR SQLSTATE 'H0004' OR SQLSTATE 'H0005' THEN
      GET STACKED DIAGNOSTICS error_code = RETURNED_SQLSTATE;
      failure := error_code;
      -- Variables survive the subtransaction; database writes do not.
    WHEN unique_violation THEN
      GET STACKED DIAGNOSTICS error_constraint = CONSTRAINT_NAME;
      IF error_constraint IS DISTINCT FROM 'seat_holds_seatId_showtimeId_key' THEN RAISE; END IF;
      -- Fresh query AFTER rollback, same ownership predicate as the API fallback.
      SELECT COALESCE(array_agg(h."seatId" ORDER BY h."seatId"),'{}'::uuid[])
      INTO "rejectedSeatIds" FROM public.seat_holds h
      JOIN public.hold_sessions hs ON hs.id=h."holdSessionId"
      WHERE h."seatId"=ANY(p_seats) AND h."expiresAt">clock_timestamp()
        AND NOT (hs."userId"=p_user AND hs."sessionHash"=p_session);
      failure := CASE WHEN cardinality("rejectedSeatIds")>0 THEN 'H0004' ELSE 'H0006' END;
  END;
  IF failure IS NOT NULL THEN
    id := NULL;
    "expiresAt" := NULL;
    "seatIds" := '{}'::uuid[];
    "serverTime" := clock_timestamp();
    "rejectedSeatIds" := COALESCE("rejectedSeatIds",p_seats);
  END IF;
  RETURN NEXT;
END;
$$;


--
-- Name: claim_hold_v4(uuid, uuid, text, uuid[], uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_hold_v4(p_show uuid, p_user uuid, p_session text, p_seats uuid[], p_id uuid, p_token uuid) RETURNS TABLE(failure text, "rejectedSeatIds" uuid[], "serverTime" timestamp with time zone, id uuid, "expiresAt" timestamp with time zone, "seatIds" uuid[])
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  show_status text;
  valid integer;
  rejected uuid[];
BEGIN
  -- Invalid inputs and validation precedence retain the existing v3 contract.
  IF cardinality(p_seats) BETWEEN 1 AND 2000
     AND NOT EXISTS (SELECT 1 FROM unnest(p_seats) AS x WHERE x IS NULL)
     AND cardinality(p_seats)=(SELECT count(DISTINCT x) FROM unnest(p_seats) AS x)
  THEN
    SELECT sh.status::text,
      (SELECT count(*)::int FROM public.seats s
        JOIN public.seat_categories c ON c.id=s."categoryId"
        WHERE s."showtimeId"=sh.id AND s.id=ANY(p_seats) AND c.price IS NOT NULL)
    INTO show_status, valid
    FROM public.showtimes sh WHERE sh.id=p_show FOR SHARE;
    IF show_status='ON_SALE' AND valid=cardinality(p_seats) THEN
      SELECT array_agg(h."seatId" ORDER BY h."seatId") INTO rejected
      FROM public.seat_holds h
      JOIN public.hold_sessions hs ON hs.id=h."holdSessionId"
      WHERE h."seatId"=ANY(p_seats) AND h."expiresAt">clock_timestamp()
        AND NOT (hs."userId"=p_user AND hs."sessionHash"=p_session);
      IF cardinality(rejected)>0 THEN
        RETURN QUERY SELECT 'H0004'::text,rejected,clock_timestamp(),
          NULL::uuid,NULL::timestamptz,'{}'::uuid[];
        RETURN;
      END IF;
    END IF;
  END IF;
  -- Races after the read, mixed sets, expiry and retry remain governed by v3's
  -- constraints, original deadline and rollback subtransaction. No cached grant.
  RETURN QUERY SELECT * FROM public.claim_hold_v3(p_show,p_user,p_session,p_seats,p_id,p_token);
END;
$$;


--
-- Name: claim_hold_v5(uuid, uuid, text, uuid[], uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_hold_v5(p_show uuid, p_user uuid, p_session text, p_seats uuid[], p_id uuid, p_token uuid) RETURNS TABLE(failure text, "rejectedSeatIds" uuid[], "serverTime" timestamp with time zone, id uuid, "expiresAt" timestamp with time zone, "seatIds" uuid[])
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE cap integer; owned integer; demo boolean;
BEGIN
  PERFORM 1 FROM public.users u WHERE u.id=p_user FOR UPDATE;
  PERFORM set_config('app.actor_id',p_user::text,true);
  SELECT sh."maxTicketsPerUser",sh."isDemo" INTO cap,demo FROM public.showtimes sh WHERE sh.id=p_show FOR SHARE;
  IF demo THEN
    RETURN QUERY SELECT 'H0008'::text,p_seats,clock_timestamp(),NULL::uuid,NULL::timestamptz,'{}'::uuid[]; RETURN;
  END IF;
  IF cap IS NOT NULL THEN
    SELECT count(*)::integer INTO owned FROM (
      SELECT h."seatId" FROM public.seat_holds h JOIN public.hold_sessions hs ON hs.id=h."holdSessionId"
        WHERE hs."userId"=p_user AND h."showtimeId"=p_show AND h."expiresAt">clock_timestamp()
      UNION SELECT oi."seatId" FROM public.order_items oi JOIN public.orders o ON o.id=oi."orderId"
        WHERE o."userId"=p_user AND o."showtimeId"=p_show AND (o.status IN ('PAID','NEEDS_REVIEW') OR (o.status IN ('PENDING','PENDING_PAYMENT') AND o."paymentExpiresAt">clock_timestamp()))
      UNION SELECT unnest(p_seats)
    ) inventory;
    IF owned>cap THEN
      RETURN QUERY SELECT 'H0007'::text,p_seats,clock_timestamp(),NULL::uuid,NULL::timestamptz,'{}'::uuid[]; RETURN;
    END IF;
  END IF;
  RETURN QUERY SELECT * FROM public.claim_hold_v4(p_show,p_user,p_session,p_seats,p_id,p_token);
END $$;


