-- Name: set_legacy_order_subtotal_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_legacy_order_subtotal_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW."couponId" IS NULL AND NEW."discountAmount" = 0
     AND NEW."subtotalAmount" = 0 AND NEW."totalAmount" > 0 THEN
    NEW."subtotalAmount" := NEW."totalAmount";
  END IF;
  RETURN NEW;
END;
$$;


