    id uuid NOT NULL,
    name text NOT NULL,
    description text NOT NULL,
    location text NOT NULL,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    "organizerId" uuid NOT NULL,
    "createdAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) with time zone NOT NULL,
    "posterPath" text,
    "mobilePosterPath" text,
    "bannerPath" text,
    "categoryLabel" text
);


--
-- Name: hold_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hold_sessions (
    id uuid NOT NULL,
    "showtimeId" uuid NOT NULL,
    "userId" uuid NOT NULL,
    "sessionHash" text NOT NULL,
    token uuid NOT NULL,
    "expiresAt" timestamp(3) with time zone NOT NULL,
    "createdAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "expectedSeatIds" uuid[] DEFAULT ARRAY[]::uuid[] NOT NULL
);


--
-- Name: mail_retry_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mail_retry_requests (
    "requestId" uuid NOT NULL,
    "actorId" uuid NOT NULL,
    "sourceId" uuid NOT NULL,
    kind text NOT NULL,
    "deliveryId" uuid NOT NULL,
    "createdAt" timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: notification_mail; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notification_mail (
    id uuid NOT NULL,
    "orderId" uuid NOT NULL,
    "recipientId" uuid NOT NULL,
    "showtimeId" uuid NOT NULL,
    kind text NOT NULL,
    version integer NOT NULL,
    "changeId" uuid,
    "dedupeKey" text NOT NULL,
    "parentId" uuid,
    status text DEFAULT 'QUEUED'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    "nextAttemptAt" timestamp with time zone DEFAULT now() NOT NULL,
    "leaseToken" uuid,
    "leaseUntil" timestamp with time zone,
    "failureCode" text,
    "sentAt" timestamp with time zone,
    "createdAt" timestamp with time zone DEFAULT now() NOT NULL,
    "updatedAt" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT notification_mail_attempts_check CHECK (((attempts >= 0) AND (attempts <= 3))),
    CONSTRAINT notification_mail_kind_check CHECK ((kind = ANY (ARRAY['REMINDER'::text, 'RESCHEDULED'::text]))),
    CONSTRAINT notification_mail_status_check CHECK ((status = ANY (ARRAY['QUEUED'::text, 'SENDING'::text, 'SENT'::text, 'FAILED'::text, 'CANCELLED'::text])))
);


--
-- Name: offline_scan_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.offline_scan_logs (
    id uuid NOT NULL,
    "scanId" uuid NOT NULL,
    "ticketCode" text NOT NULL,
    "showtimeId" uuid NOT NULL,
    "gateId" uuid,
    "staffId" uuid NOT NULL,
    "deviceId" text NOT NULL,
    "scannedAt" timestamp(3) with time zone NOT NULL,
    status text NOT NULL,
    message text,
    "createdAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "payloadHash" text,
    receipt jsonb,
    mode text,
    "deviceSentAt" timestamp(3) with time zone,
    "clockOffsetMs" double precision,
    CONSTRAINT offline_scan_mode_check CHECK (((mode IS NULL) OR (mode = ANY (ARRAY['offline_admission'::text, 'online_confirmation'::text]))))
);


--
-- Name: operation_mail; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.operation_mail (
    id uuid NOT NULL,
    "orderId" uuid NOT NULL,
    status text DEFAULT 'QUEUED'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    "nextAttemptAt" timestamp with time zone DEFAULT now() NOT NULL,
    "leaseUntil" timestamp with time zone,
    "leaseToken" uuid,
    "createdAt" timestamp with time zone DEFAULT now() NOT NULL,
    "sentAt" timestamp with time zone
);


--
-- Name: order_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.order_items (
    id uuid NOT NULL,
    "orderId" uuid NOT NULL,
    "seatId" uuid NOT NULL,
    "categoryName" text NOT NULL,
    "unitPrice" integer NOT NULL,
    "tierName" text,
    "checkedInAt" timestamp(3) with time zone,
    CONSTRAINT "order_items_unitPrice_check" CHECK (("unitPrice" >= 0))
);


--
-- Name: order_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.order_logs (
    id uuid NOT NULL,
    "orderId" uuid NOT NULL,
    type text NOT NULL,
    "attemptNo" integer,
    detail jsonb,
    "createdAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: orders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.orders (
    id uuid NOT NULL,
    "userId" uuid NOT NULL,
    "showtimeId" uuid NOT NULL,
    "holdSessionId" uuid,
    "holdToken" uuid,
    status public."OrderStatus" DEFAULT 'PENDING_PAYMENT'::public."OrderStatus" NOT NULL,
    "paymentExpiresAt" timestamp(3) with time zone NOT NULL,
    "totalAmount" integer NOT NULL,
    "createdAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) with time zone NOT NULL,
    "eventId" uuid,
    "expiresAt" timestamp(3) with time zone,
    "subtotalAmount" integer DEFAULT 0 NOT NULL,
    "discountAmount" integer DEFAULT 0 NOT NULL,
    "couponCodeSnapshot" text,
    "couponTypeSnapshot" text,
    "couponValueSnapshot" integer,
    "couponId" uuid,
    CONSTRAINT orders_coupon_amount_check CHECK ((("subtotalAmount" >= 0) AND ("discountAmount" >= 0) AND ("discountAmount" <= "subtotalAmount") AND ("totalAmount" = ("subtotalAmount" - "discountAmount"))))
);


--
-- Name: password_resets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.password_resets (
    "tokenHash" text NOT NULL,
    "userId" uuid NOT NULL,
    "encryptedToken" text NOT NULL,
    "expiresAt" timestamp with time zone NOT NULL,
    "consumedAt" timestamp with time zone,
    status text DEFAULT 'QUEUED'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    "nextAttemptAt" timestamp with time zone DEFAULT now() NOT NULL,
    "leaseToken" uuid,
    "leaseUntil" timestamp with time zone,
    "createdAt" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT password_resets_attempts_check CHECK (((attempts >= 0) AND (attempts <= 3)))
);


--
-- Name: payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payments (
    id uuid NOT NULL,
    "orderId" uuid NOT NULL,
    amount integer NOT NULL,
    status public."PaymentStatus" DEFAULT 'INITIATED'::public."PaymentStatus" NOT NULL,
    gateway text NOT NULL,
    "gatewayRef" text NOT NULL,
    "transactionId" text,
    "createdAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) with time zone NOT NULL,
    "attemptNo" integer DEFAULT 1 NOT NULL
);


--
-- Name: reconciliation_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reconciliation_runs (
    id uuid NOT NULL,
    "fileHash" text NOT NULL,
    "actorId" uuid NOT NULL,
    "periodStart" timestamp with time zone NOT NULL,
    "periodEnd" timestamp with time zone NOT NULL,
    result jsonb NOT NULL,
    "createdAt" timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: refund_attempts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.refund_attempts (
    id uuid NOT NULL,
    "refundId" uuid NOT NULL,
    attempt integer NOT NULL,
    status text NOT NULL,
    reason text,
    "createdAt" timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: refunds; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.refunds (
    id uuid NOT NULL,
    "orderId" uuid NOT NULL,
    amount integer NOT NULL,
    status text DEFAULT 'QUEUED'::text NOT NULL,
    reason text NOT NULL,
    "actorId" uuid NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    "nextAttemptAt" timestamp with time zone DEFAULT now() NOT NULL,
    "leaseUntil" timestamp with time zone,
    "leaseToken" uuid,
    "providerRef" text,
    "failureCode" text,
    "completedAt" timestamp with time zone,
    "createdAt" timestamp with time zone DEFAULT now() NOT NULL,
    "updatedAt" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT refunds_amount_check CHECK ((amount >= 0)),
    CONSTRAINT refunds_attempts_check CHECK (((attempts >= 0) AND (attempts <= 3))),
    CONSTRAINT refunds_status_check CHECK ((status = ANY (ARRAY['QUEUED'::text, 'SENDING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'UNKNOWN'::text])))
);


--
-- Name: registration_consents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.registration_consents (
    "userId" uuid NOT NULL,
    "noticeVersion" text NOT NULL,
    purpose text NOT NULL,
    status text NOT NULL,
    "acceptedAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT registration_consents_status_check CHECK ((status = ANY (ARRAY['GRANTED'::text, 'WITHDRAWN'::text])))
);


--
-- Name: roles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.roles (
    id uuid NOT NULL,
    name text NOT NULL
);


--
-- Name: scanner_snapshot_cursors; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.scanner_snapshot_cursors (
    id uuid NOT NULL,
    "showtimeId" uuid NOT NULL,
    "staffId" uuid NOT NULL,
    version text NOT NULL,
    tickets jsonb NOT NULL,
    "createdAt" timestamp(3) with time zone DEFAULT clock_timestamp() NOT NULL,
    "expiresAt" timestamp(3) with time zone DEFAULT (clock_timestamp() + '04:00:00'::interval) NOT NULL
);


--
-- Name: schedule_changes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.schedule_changes (
    id uuid NOT NULL,
    "showtimeId" uuid NOT NULL,
    "actorId" uuid NOT NULL,
    "requestId" uuid NOT NULL,
    "oldTime" timestamp with time zone NOT NULL,
    "newTime" timestamp with time zone NOT NULL,
    reason text NOT NULL,
    version integer NOT NULL,
    "createdAt" timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: seat_categories; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.seat_categories (
    id uuid NOT NULL,
    "showtimeId" uuid NOT NULL,
    name text NOT NULL,
    price integer,
    CONSTRAINT seat_categories_price_check CHECK (((price IS NULL) OR (price >= 0)))
);


--
-- Name: seat_holds; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.seat_holds (
    "seatId" uuid NOT NULL,
    "showtimeId" uuid NOT NULL,
    "holdSessionId" uuid NOT NULL,
    token uuid NOT NULL,
    "expiresAt" timestamp(3) with time zone NOT NULL,
    "acquiredAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: seats; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.seats (
    id uuid NOT NULL,
    "showtimeId" uuid NOT NULL,
    "categoryId" uuid NOT NULL,
    "row" text NOT NULL,
    "seatNumber" integer NOT NULL,
    "isSold" boolean DEFAULT false NOT NULL,
    CONSTRAINT "seats_seatNumber_check" CHECK (("seatNumber" > 0))
);


--
-- Name: sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sessions (
    "tokenHash" text NOT NULL,
    "userId" uuid NOT NULL,
    "expiresAt" timestamp(3) with time zone NOT NULL,
    "createdAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: showtime_cancellations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.showtime_cancellations (
    "showtimeId" uuid NOT NULL,
    "actorId" uuid NOT NULL,
    reason text NOT NULL,
    status text DEFAULT 'QUEUED'::text NOT NULL,
    "failureCode" text,
    "createdAt" timestamp with time zone DEFAULT now() NOT NULL,
    "updatedAt" timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: showtime_staff; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.showtime_staff (
    id uuid NOT NULL,
    "showtimeId" uuid NOT NULL,
    "userId" uuid NOT NULL,
    "assignedAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: showtimes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.showtimes (
    id uuid NOT NULL,
    "eventId" uuid NOT NULL,
    "startTime" timestamp(3) with time zone NOT NULL,
    "seatMapId" text,
    "createdAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) with time zone NOT NULL,
    status public."ShowtimeStatus" DEFAULT 'DRAFT'::public."ShowtimeStatus" NOT NULL,
    "structureLocked" boolean DEFAULT false NOT NULL,
    "maxTicketsPerUser" integer DEFAULT 4,
    "isDemo" boolean DEFAULT false NOT NULL,
    "scheduleVersion" integer DEFAULT 0 NOT NULL
);


--
-- Name: ticket_admissions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ticket_admissions (
    id uuid NOT NULL,
    "ticketId" uuid NOT NULL,
    "showtimeId" uuid NOT NULL,
    "gateId" uuid NOT NULL,
    "gateName" text NOT NULL,
    "staffId" uuid NOT NULL,
    "staffName" text NOT NULL,
    "requestId" uuid NOT NULL,
    kind text NOT NULL,
    reason text,
    "ownerConfirmed" boolean DEFAULT false NOT NULL,
    "enteredAt" timestamp(3) with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT ticket_admissions_check CHECK ((((kind = 'NORMAL'::text) AND (reason IS NULL) AND ("ownerConfirmed" = false)) OR ((kind = 'EXCEPTION'::text) AND (reason IS NOT NULL) AND (reason !~ '^[[:space:]]*$'::text) AND ((length(reason) >= 1) AND (length(reason) <= 500)) AND ("ownerConfirmed" = true)))),
    CONSTRAINT ticket_admissions_kind_check CHECK ((kind = ANY (ARRAY['NORMAL'::text, 'EXCEPTION'::text])))
);


--
-- Name: ticket_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ticket_logs (
    id uuid NOT NULL,
    "ticketId" uuid NOT NULL,
    action text NOT NULL,
    "actorId" uuid,
    detail jsonb,
    "createdAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: ticket_mail_deliveries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ticket_mail_deliveries (
    id uuid NOT NULL,
    "orderId" uuid NOT NULL,
    "dedupeKey" text NOT NULL,
    status text DEFAULT 'QUEUED'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    "nextAttemptAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "leaseUntil" timestamp(3) with time zone,
    "leaseToken" uuid,
    "failureCode" text,
    "sentAt" timestamp(3) with time zone,
    "createdAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "recipientEmail" text,
    "ticketId" uuid,
    CONSTRAINT ticket_mail_deliveries_attempts_check CHECK (((attempts >= 0) AND (attempts <= 3))),
    CONSTRAINT ticket_mail_deliveries_status_check CHECK ((status = ANY (ARRAY['QUEUED'::text, 'SENDING'::text, 'SENT'::text, 'FAILED'::text, 'CANCELLED'::text])))
);


--
-- Name: tickets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tickets (
    id uuid NOT NULL,
    "orderId" uuid,
    "showtimeId" uuid NOT NULL,
    "seatId" uuid,
    code text NOT NULL,
    "seatLabel" text NOT NULL,
    "ticketType" text NOT NULL,
    status public."TicketStatus" DEFAULT 'VALID'::public."TicketStatus" NOT NULL,
    "checkedInAt" timestamp(3) with time zone,
    "cancelledAt" timestamp(3) with time zone,
    price integer DEFAULT 0 NOT NULL,
    "createdAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "keyId" text,
    signature text,
    "ownerEmail" text,
    "transferredToEmail" text,
    "reminderSentAt" timestamp(3) with time zone,
    "remindedStartTime" timestamp(3) with time zone
);


--
-- Name: user_admin_audit; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_admin_audit (
    id uuid NOT NULL,
    "performedById" uuid NOT NULL,
    "targetUserId" uuid NOT NULL,
    action text NOT NULL,
    "oldValue" text,
    "newValue" text,
    "createdAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT user_admin_audit_action_check CHECK ((action = ANY (ARRAY['CREATE_EMPLOYEE'::text, 'CHANGE_ROLE'::text, 'TOGGLE_STATUS'::text, 'ASSIGN_GATE'::text, 'REVOKE_GATE'::text])))
);


--
-- Name: user_roles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_roles (
    "userId" uuid NOT NULL,
    "roleId" uuid NOT NULL
);


--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    id uuid NOT NULL,
    email text NOT NULL,
    password text NOT NULL,
    "isEmailVerified" boolean DEFAULT false NOT NULL,
    "activationToken" text,
    "activationExpires" timestamp(3) with time zone,
    "createdAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) with time zone NOT NULL,
    "isActive" boolean DEFAULT true NOT NULL,
    "fullName" text
);


--
-- Name: waitlist_availability_signals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.waitlist_availability_signals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    "showtimeId" uuid NOT NULL,
    "releasedCount" integer NOT NULL,
    status public."WaitlistSignalStatus" DEFAULT 'PENDING'::public."WaitlistSignalStatus" NOT NULL,
    "createdAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "processedAt" timestamp(3) with time zone,
    CONSTRAINT waitlist_availability_signals_count_check CHECK (("releasedCount" > 0))
);


--
-- Name: waitlist_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.waitlist_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    "showtimeId" uuid NOT NULL,
    "userId" uuid NOT NULL,
    status public."WaitlistEntryStatus" DEFAULT 'ACTIVE'::public."WaitlistEntryStatus" NOT NULL,
    "createdAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "notifiedAt" timestamp(3) with time zone,
    "cancelledAt" timestamp(3) with time zone
);


--
-- Name: waitlist_notifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.waitlist_notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    "entryId" uuid NOT NULL,
    "signalId" uuid NOT NULL,
    status public."WaitlistNoticeStatus" DEFAULT 'QUEUED'::public."WaitlistNoticeStatus" NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    "nextAttemptAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "leaseToken" uuid,
    "leaseUntil" timestamp(3) with time zone,
    "sentAt" timestamp(3) with time zone,
    "failureCode" text,
    "createdAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT waitlist_notifications_attempts_check CHECK ((attempts >= 0))
);


